def _step(name: str):
    def decorator(fn):
        async def wrapper(*args, **kwargs):
            if _step_done(name):
                print(f"  [SKIP] {name} (already done)")
                return
            print(f"  [RUN ] {name} ...")
            _mark_step(name, "running")
            try:
                await fn(*args, **kwargs)
                _mark_step(name, "done")
            except Exception as exc:
                _mark_step(name, "failed", str(exc))
        return wrapper
    return decorator
